import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  const totalProblems = problems.length;
  const solved = user?.stats?.problemsSolved || 0;
  const attempts = user?.stats?.totalAttempts || 0;
  const successRate = attempts > 0 ? Math.round((solved / attempts) * 100) : 0;

  return (
    <div style={styles.container}>
      {/* ===== STATS ROW ===== */}
      <div style={styles.statsRow}>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>📚</div>
          <div>
            <div style={styles.statNumber}>{totalProblems}</div>
            <div style={styles.statLabel}>Total Problems</div>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>✅</div>
          <div>
            <div style={styles.statNumber}>{solved}</div>
            <div style={styles.statLabel}>Solved</div>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>📝</div>
          <div>
            <div style={styles.statNumber}>{attempts}</div>
            <div style={styles.statLabel}>Attempts</div>
          </div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statIcon}>🏆</div>
          <div>
            <div style={styles.statNumber}>{successRate}%</div>
            <div style={styles.statLabel}>Success Rate</div>
          </div>
        </div>
      </div>

      {/* ===== ASSIGNMENTS ===== */}
      <div style={styles.assignmentsSection}>
        <div style={styles.sectionHeader}>
          <h2 style={styles.sectionTitle}>📋 Assignments</h2>
          <span style={styles.sectionBadge}>{problems.length} Active</span>
        </div>

        <div style={styles.problemGrid}>
          {loading ? (
            <div style={styles.loadingState}>
              <div className="spinner"></div>
              <p>Loading assignments...</p>
            </div>
          ) : problems.length === 0 ? (
            <div style={styles.emptyState}>
              <span style={styles.emptyIcon}>📭</span>
              <p>No assignments available</p>
            </div>
          ) : (
            problems.map((problem, index) => (
              <div key={problem._id} style={styles.problemCard}>
                <div style={styles.cardHeader}>
                  <span style={styles.programNumber}>PROGRAM-{index + 1}</span>
                  <span style={{
                    ...styles.difficultyBadge,
                    background:
                      problem.difficulty === 'Easy'
                        ? '#10b981'
                        : problem.difficulty === 'Medium'
                        ? '#f59e0b'
                        : '#ef4444',
                  }}>
                    {problem.difficulty || 'Easy'}
                  </span>
                </div>
                
                <div style={styles.problemTitle}>{problem.title}</div>
                
                <div style={styles.metaRow}>
                  <span style={styles.problemId}>FS-A1-Audi-2027</span>
                  <span style={styles.labBadge}>LAB</span>
                </div>
                
                <div style={styles.startedBox}>
                  <span style={styles.startedLabel}>📅 STARTED</span>
                  <span style={styles.startedDate}>
                    {new Date(problem.createdAt).toLocaleDateString('en-US', {
                      weekday: 'long',
                      day: 'numeric',
                      month: 'long',
                      year: 'numeric',
                    })}
                  </span>
                </div>
                
                <button
                  style={styles.attemptBtn}
                  onClick={() => navigate(`/problems/${problem._id}`)}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = '#6C63FF';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                    e.currentTarget.style.boxShadow = '0 8px 25px rgba(108, 99, 255, 0.35)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = '#4A3FCF';
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = 'none';
                  }}
                >
                  ATTEMPT →
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

// ===== PREMIUM CSS STYLES =====
const styles = {
  container: {
    minHeight: '100vh',
    background: '#f8fafc',
    fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },

  // ===== STATS ROW =====
  statsRow: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '20px',
    padding: '24px 28px',
    background: 'white',
    borderBottom: '1px solid #f1f5f9',
  },
  statCard: {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
    padding: '16px 20px',
    background: '#f8fafc',
    borderRadius: '16px',
    transition: 'all 0.3s ease',
    border: '1px solid transparent',
  },
  statIcon: {
    fontSize: '28px',
    width: '48px',
    height: '48px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'white',
    borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
  },
  statNumber: {
    fontSize: '26px',
    fontWeight: 700,
    color: '#0f172a',
    lineHeight: '1.2',
  },
  statLabel: {
    fontSize: '13px',
    color: '#94a3b8',
    fontWeight: 500,
  },

  // ===== ASSIGNMENTS =====
  assignmentsSection: {
    padding: '24px 28px 32px 28px',
  },
  sectionHeader: {
    display: 'flex',
